const $=s=>document.querySelector(s);let finish='sand',current='One',selection=[];const products={One:{price:249,desc:'Your everyday listening companion. A compact, sculptural speaker envisioned for warm, room-filling sound.'},Go:{price:149,desc:'A portable companion for wherever the day takes you. Small in scale, full of character.'},Studio:{price:449,desc:'An expansive listening concept for your favourite space. A wider form with a deeper presence.'}};const colors={sand:['#b4aa95','#d5cdbd','#807762'],charcoal:['#50534b','#777b70','#32362f'],clay:['#ad6d52','#cf967b','#794333']};document.querySelectorAll('.swatch').forEach(b=>b.addEventListener('click',()=>{finish=b.dataset.finish;document.querySelectorAll('.swatch').forEach(s=>{s.classList.toggle('selected',s===b);s.setAttribute('aria-pressed',s===b)});['--shell','--shell-light','--shell-dark'].forEach((v,i)=>document.documentElement.style.setProperty(v,colors[finish][i]));$('#finishLabel').textContent=finish[0].toUpperCase()+finish.slice(1)}));let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;function setMotion(){document.body.classList.toggle('paused',paused);$('#motion').textContent=paused?'▷ Resume motion':'Ⅱ Pause motion';$('#motion').setAttribute('aria-pressed',paused)}setMotion();$('#motion').addEventListener('click',()=>{paused=!paused;setMotion()});$('#stage').addEventListener('pointermove',e=>{if(paused||e.pointerType==='touch')return;const r=e.currentTarget.getBoundingClientRect();const x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;$('#speaker').style.transform=`rotateX(${-12-y*12}deg) rotateY(${-24+x*25}deg) rotateZ(7deg)`});$('#stage').addEventListener('pointerleave',()=>$('#speaker').style.transform='');document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>{current=b.dataset.product;$('#dialogTitle').textContent='Aura '+current;$('#dialogDesc').textContent=products[current].desc;$('#dialogPrice').textContent='$'+products[current].price;$('#dialogFinish').textContent=current==='One'?finish[0].toUpperCase()+finish.slice(1)+' finish':current==='Go'?'Charcoal finish':'Clay finish';$('.dialog-visual .mini-speaker').className='mini-speaker '+(current==='Go'?'portable':current==='Studio'?'wide':'');$('#productDialog').showModal()}));document.querySelectorAll('dialog .close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#addSelection').addEventListener('click',()=>{selection.push({model:current,finish:$('#dialogFinish').textContent});$('#count').textContent=selection.length;$('#productDialog').close();$('#toast').textContent='Aura '+current+' added to your selection';$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)});function renderSelection(){const root=$('#selectionItems');root.replaceChildren();if(!selection.length){const p=document.createElement('p');p.textContent='Your collection is waiting. Explore the speakers to add a favourite.';root.append(p)}selection.forEach((item,i)=>{const row=document.createElement('div');row.className='selection-item';const label=document.createElement('span');label.textContent=`Aura ${item.model} · ${item.finish} · $${products[item.model].price}`;const b=document.createElement('button');b.textContent='Remove';b.setAttribute('aria-label','Remove Aura '+item.model);b.onclick=()=>{selection.splice(i,1);$('#count').textContent=selection.length;renderSelection()};row.append(label,b);root.append(row)})}$('#bag').addEventListener('click',()=>{renderSelection();$('#selectionDialog').showModal()});$('#continue').addEventListener('click',()=>{$('#selectionDialog').close();$('#collection').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})});
